package com.zachgodsell.bankitemvalue;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(BankItemValueConfig.GROUP)
public interface BankItemValueConfig extends Config
{
	String GROUP = "bankitemvalue";

	@ConfigSection(
		name = "General",
		description = "Price source, formatting and where the overlay applies",
		position = 0
	)
	String generalSection = "general";

	@ConfigSection(
		name = "Display",
		description = "How the value text is drawn on each item",
		position = 1
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Highlighting",
		description = "How items are highlighted with their tier colour",
		position = 2
	)
	String highlightingSection = "highlighting";

	@ConfigSection(
		name = "Value tiers",
		description = "Value thresholds and the colour used for each tier",
		position = 3
	)
	String tiersSection = "tiers";

	// General

	@ConfigItem(
		keyName = "showValueText",
		name = "Show value text",
		description = "Draw the item's total value as text on the item",
		position = 0,
		section = generalSection
	)
	default boolean showValueText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "priceSource",
		name = "Price source",
		description = "Which price is used per item: Grand Exchange price, high alchemy value, or the highest of the two",
		position = 1,
		section = generalSection
	)
	default PriceSource priceSource()
	{
		return PriceSource.GRAND_EXCHANGE;
	}

	@ConfigItem(
		keyName = "valueFormat",
		name = "Value format",
		description = "How values are written: Short (73K), Decimal (73.5K) or Exact (73,542)",
		position = 2,
		section = generalSection
	)
	default ValueFormat valueFormat()
	{
		return ValueFormat.DECIMAL;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "hideUnderValue",
		name = "Hide under value",
		description = "Items whose total value is below this amount show no overlay at all. 0 shows everything",
		position = 3,
		section = generalSection
	)
	default int hideUnderValue()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "applyToInventory",
		name = "Apply to inventory",
		description = "Also overlay the inventory side panel while the bank is open",
		position = 4,
		section = generalSection
	)
	default boolean applyToInventory()
	{
		return false;
	}

	// Display

	@ConfigItem(
		keyName = "textPosition",
		name = "Text position",
		description = "Corner of the item where the value text is drawn. The game draws stack counts at the top left",
		position = 0,
		section = displaySection
	)
	default TextPosition textPosition()
	{
		return TextPosition.BOTTOM_LEFT;
	}

	@ConfigItem(
		keyName = "textShadow",
		name = "Text shadow",
		description = "Draw a one-pixel shadow under the value text for legibility",
		position = 1,
		section = displaySection
	)
	default boolean textShadow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useSmallFont",
		name = "Use small font",
		description = "Use the small Runescape font so the text fits inside a bank item cell",
		position = 2,
		section = displaySection
	)
	default boolean useSmallFont()
	{
		return true;
	}

	// Highlighting

	@ConfigItem(
		keyName = "highlightMode",
		name = "Highlight mode",
		description = "How each item shows its tier colour: coloured text, a box outline, a filled box, outline plus text, or nothing",
		position = 0,
		section = highlightingSection
	)
	default HighlightMode highlightMode()
	{
		return HighlightMode.TEXT_ONLY;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "fillOpacity",
		name = "Fill opacity",
		description = "Opacity of the filled box in Box fill mode. 0 is invisible, 255 is solid",
		position = 1,
		section = highlightingSection
	)
	default int fillOpacity()
	{
		return 40;
	}

	// Value tiers

	@Alpha
	@ConfigItem(
		keyName = "defaultColor",
		name = "Default colour",
		description = "Colour for items below every enabled tier threshold",
		position = 0,
		section = tiersSection
	)
	default Color defaultColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "lowEnabled",
		name = "Low tier",
		description = "Enable the low value tier",
		position = 1,
		section = tiersSection
	)
	default boolean lowEnabled()
	{
		return true;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "lowThreshold",
		name = "Low threshold",
		description = "Items worth at least this amount use the low tier colour",
		position = 2,
		section = tiersSection
	)
	default int lowThreshold()
	{
		return 20_000;
	}

	@Alpha
	@ConfigItem(
		keyName = "lowColor",
		name = "Low colour",
		description = "Colour for items in the low value tier",
		position = 3,
		section = tiersSection
	)
	default Color lowColor()
	{
		return new Color(0x66B2FF);
	}

	@ConfigItem(
		keyName = "mediumEnabled",
		name = "Medium tier",
		description = "Enable the medium value tier",
		position = 4,
		section = tiersSection
	)
	default boolean mediumEnabled()
	{
		return true;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "mediumThreshold",
		name = "Medium threshold",
		description = "Items worth at least this amount use the medium tier colour",
		position = 5,
		section = tiersSection
	)
	default int mediumThreshold()
	{
		return 100_000;
	}

	@Alpha
	@ConfigItem(
		keyName = "mediumColor",
		name = "Medium colour",
		description = "Colour for items in the medium value tier",
		position = 6,
		section = tiersSection
	)
	default Color mediumColor()
	{
		return new Color(0x99FF99);
	}

	@ConfigItem(
		keyName = "highEnabled",
		name = "High tier",
		description = "Enable the high value tier",
		position = 7,
		section = tiersSection
	)
	default boolean highEnabled()
	{
		return true;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "highThreshold",
		name = "High threshold",
		description = "Items worth at least this amount use the high tier colour",
		position = 8,
		section = tiersSection
	)
	default int highThreshold()
	{
		return 1_000_000;
	}

	@Alpha
	@ConfigItem(
		keyName = "highColor",
		name = "High colour",
		description = "Colour for items in the high value tier",
		position = 9,
		section = tiersSection
	)
	default Color highColor()
	{
		return new Color(0xFF9600);
	}

	@ConfigItem(
		keyName = "insaneEnabled",
		name = "Insane tier",
		description = "Enable the insane value tier",
		position = 10,
		section = tiersSection
	)
	default boolean insaneEnabled()
	{
		return true;
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "insaneThreshold",
		name = "Insane threshold",
		description = "Items worth at least this amount use the insane tier colour",
		position = 11,
		section = tiersSection
	)
	default int insaneThreshold()
	{
		return 10_000_000;
	}

	@Alpha
	@ConfigItem(
		keyName = "insaneColor",
		name = "Insane colour",
		description = "Colour for items in the insane value tier",
		position = 12,
		section = tiersSection
	)
	default Color insaneColor()
	{
		return new Color(0xFF66B2);
	}
}

package com.zachgodsell.bankitemvalue;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.QuantityFormatter;

@Singleton
class BankItemValueOverlay extends WidgetItemOverlay
{
	private static final CacheEntry HIDDEN = new CacheEntry(0, null, null, null);

	private final ItemManager itemManager;
	private final BankItemValueConfig config;

	private final Map<Long, CacheEntry> cache = new ConcurrentHashMap<>();

	// Config resolved into fields on start up and on config change; the render
	// path never reads the config proxy.
	private volatile boolean showValueText;
	private volatile PriceSource priceSource;
	private volatile ValueFormat valueFormat;
	private volatile long hideUnderValue;
	private volatile boolean applyToInventory;
	private volatile TextPosition textPosition;
	private volatile boolean textShadow;
	private volatile boolean useSmallFont;
	private volatile HighlightMode highlightMode;
	private volatile int fillOpacity;
	private volatile Color defaultColor;
	private volatile List<ValueTier> tiers = new ArrayList<>();

	@Inject
	private BankItemValueOverlay(ItemManager itemManager, BankItemValueConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		showOnBank();
		showOnInterfaces(InterfaceID.BANKSIDE);
		updateConfig();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (highlightMode == HighlightMode.NONE)
		{
			return;
		}

		// A bank slot with quantity 0 is a placeholder
		final int quantity = widgetItem.getQuantity();
		if (quantity <= 0)
		{
			return;
		}

		final int interfaceId = widgetItem.getWidget().getId() >>> 16;
		if (interfaceId == InterfaceID.BANKSIDE && !applyToInventory)
		{
			return;
		}

		final long key = ((long) itemId << 32) | (quantity & 0xffffffffL);
		CacheEntry entry = cache.get(key);
		if (entry == null)
		{
			entry = computeEntry(itemId, quantity);
			cache.put(key, entry);
		}

		if (entry == HIDDEN)
		{
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		final Font originalFont = graphics.getFont();
		final Color originalColor = graphics.getColor();
		try
		{
			if (highlightMode == HighlightMode.BOX_FILL)
			{
				graphics.setColor(entry.fillColor);
				graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
				return;
			}

			if (highlightMode == HighlightMode.BOX_OUTLINE || highlightMode == HighlightMode.OUTLINE_AND_TEXT)
			{
				graphics.setColor(entry.color);
				graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
			}

			final boolean drawText = showValueText
				&& (highlightMode == HighlightMode.TEXT_ONLY || highlightMode == HighlightMode.OUTLINE_AND_TEXT);
			if (!drawText)
			{
				return;
			}

			graphics.setFont(useSmallFont ? FontManager.getRunescapeSmallFont() : FontManager.getRunescapeFont());

			final FontMetrics metrics = graphics.getFontMetrics();
			final int textWidth = metrics.stringWidth(entry.text);
			final int textX;
			final int textY;
			switch (textPosition)
			{
				case TOP_LEFT:
					textX = bounds.x;
					textY = bounds.y + metrics.getAscent();
					break;
				case TOP_RIGHT:
					textX = bounds.x + bounds.width - textWidth;
					textY = bounds.y + metrics.getAscent();
					break;
				case BOTTOM_RIGHT:
					textX = bounds.x + bounds.width - textWidth;
					textY = bounds.y + bounds.height - 1;
					break;
				case CENTER:
					textX = bounds.x + (bounds.width - textWidth) / 2;
					textY = bounds.y + (bounds.height + metrics.getAscent()) / 2;
					break;
				case BOTTOM_LEFT:
				default:
					textX = bounds.x;
					textY = bounds.y + bounds.height - 1;
					break;
			}

			if (textShadow)
			{
				graphics.setColor(Color.BLACK);
				graphics.drawString(entry.text, textX + 1, textY + 1);
			}
			graphics.setColor(entry.color);
			graphics.drawString(entry.text, textX, textY);
		}
		finally
		{
			graphics.setFont(originalFont);
			graphics.setColor(originalColor);
		}
	}

	private CacheEntry computeEntry(int itemId, int quantity)
	{
		final long unitPrice = unitPrice(itemId);
		if (unitPrice <= 0)
		{
			return HIDDEN;
		}

		final long value = unitPrice * quantity;
		if (value < hideUnderValue)
		{
			return HIDDEN;
		}

		final Color color = ValueTier.resolve(value, tiers, defaultColor);
		final Color fillColor = new Color(color.getRed(), color.getGreen(), color.getBlue(), fillOpacity);
		final String text = formatValue(value, valueFormat);
		return new CacheEntry(value, text, color, fillColor);
	}

	private long unitPrice(int itemId)
	{
		// getItemPrice resolves noted items to their unnoted counterpart itself
		final long gePrice = priceSource == PriceSource.HIGH_ALCHEMY ? 0 : itemManager.getItemPrice(itemId);

		int haPrice = 0;
		if (priceSource != PriceSource.GRAND_EXCHANGE)
		{
			net.runelite.api.ItemComposition composition = itemManager.getItemComposition(itemId);
			if (composition.getNote() != -1)
			{
				composition = itemManager.getItemComposition(composition.getLinkedNoteId());
			}
			haPrice = composition.getHaPrice();
		}

		return Math.max(gePrice, haPrice);
	}

	static String formatValue(long value, ValueFormat format)
	{
		switch (format)
		{
			case EXACT:
				return QuantityFormatter.formatNumber(value);
			case SHORT:
			{
				final String text = QuantityFormatter.quantityToStackSize(value);
				final int dot = text.indexOf('.');
				if (dot < 0)
				{
					return text;
				}
				final char suffix = text.charAt(text.length() - 1);
				return Character.isLetter(suffix)
					? text.substring(0, dot) + suffix
					: text.substring(0, dot);
			}
			case DECIMAL:
			default:
				return QuantityFormatter.quantityToStackSize(value);
		}
	}

	void updateConfig()
	{
		showValueText = config.showValueText();
		priceSource = config.priceSource();
		valueFormat = config.valueFormat();
		hideUnderValue = config.hideUnderValue();
		applyToInventory = config.applyToInventory();
		textPosition = config.textPosition();
		textShadow = config.textShadow();
		useSmallFont = config.useSmallFont();
		highlightMode = config.highlightMode();
		fillOpacity = config.fillOpacity();
		defaultColor = config.defaultColor();

		final List<ValueTier> newTiers = new ArrayList<>();
		if (config.lowEnabled())
		{
			newTiers.add(new ValueTier(config.lowThreshold(), config.lowColor()));
		}
		if (config.mediumEnabled())
		{
			newTiers.add(new ValueTier(config.mediumThreshold(), config.mediumColor()));
		}
		if (config.highEnabled())
		{
			newTiers.add(new ValueTier(config.highThreshold(), config.highColor()));
		}
		if (config.insaneEnabled())
		{
			newTiers.add(new ValueTier(config.insaneThreshold(), config.insaneColor()));
		}
		newTiers.sort(Comparator.comparingLong(tier -> -tier.threshold));
		tiers = newTiers;

		cache.clear();
	}

	void clearCache()
	{
		cache.clear();
	}

	private static final class CacheEntry
	{
		private final long value;
		private final String text;
		private final Color color;
		private final Color fillColor;

		private CacheEntry(long value, String text, Color color, Color fillColor)
		{
			this.value = value;
			this.text = text;
			this.color = color;
			this.fillColor = fillColor;
		}
	}
}

package com.zachgodsell.bankitemvalue;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Bank Item Value",
	description = "Overlays bank items with their value and colour-coded highlighting",
	tags = {"bank", "value", "price", "overlay", "ge", "alch"}
)
public class BankItemValuePlugin extends Plugin
{
	private static final int SHARED_BANK_GROUP = InterfaceID.SharedBank.ITEMS >>> 16;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankItemValueOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		overlay.updateConfig();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlay.clearCache();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(BankItemValueConfig.GROUP))
		{
			return;
		}

		overlay.updateConfig();
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN || event.getGroupId() == SHARED_BANK_GROUP)
		{
			overlay.clearCache();
		}
	}

	@Provides
	BankItemValueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankItemValueConfig.class);
	}
}

